contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address fromAddr, uint256 v, uint256 decimals, uint256 tosCount) public {
        vm.assume(decimals <= 18);
        uint256 n = bound(tosCount, 1, 5);

        CalleeAlwaysSucceeds callee = new CalleeAlwaysSucceeds();

        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(fromAddr, i)))));
        }

        bool ok;
        bool ret;
        try c.transfer(fromAddr, address(callee), tos, v, decimals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        assertTrue(!ok || ret);
    }
}

